// Keep user drafts intact. Archive only the exact suggestions generated by the former widget.
export function prepareWritingDraft(notes){
 if(notes['writing-editor-version']==='2')return notes;
 const next={...notes,'writing-editor-version':'2'},word=(notes['spark-word']||'Quantenquark').trim()||'Mein Wort',first=Array.from(word)[0].toLocaleUpperCase('de');
 const former=[`${word} kam zu spät. Der Rest der Welt wartete schon.`,`Ich wollte ${word} erklären. Jetzt erklärt es mich.`,`${word}. ${first}… ${first}… Wer oder was könnte hier auftauchen?`];
 if(former.includes(notes['spark-line'])){
  next['earlier-generated-line']=notes['spark-line'];
  next['spark-line']='';
 }
 return next;
}
